/// `stripeSecretKey`, `API-Key` and `first name` become `stripe_secret_key`, `api_key`, `first_name`.
fn normalize_pii_key(key: &str) -> String {
    let mut out = String::with_capacity(key.len() + 4);
    let mut previous: Option<char> = None;
    for ch in key.chars() {
        let after_word = matches!(previous, Some(p) if p.is_lowercase() || p.is_ascii_digit());
        if ch.is_uppercase() && after_word {
            out.push('_');
        }
        if ch.is_alphanumeric() {
            out.extend(ch.to_lowercase());
        } else {
            out.push('_');
        }
        previous = Some(ch);
    }
    out
}

